if(!defined('VELTRION_RUNTIME_GUARD') && file_exists(__DIR__ . '/../bootstrap/guard.php')){ @include_once __DIR__ . '/../bootstrap/guard.php'; }
  class Pipeline { public function __construct( public string $id, public string $name = 'Veltrion CI/CD Pipeline', public string $profile = 'standard', public string $status = 'CREATED', public string $branch = 'master', public string $commit = 'head', public array $stages = [], public array $artifacts = [], public array $reports = [], public int $startedAt = 0, public int $finishedAt = 0 ) { if ($this->startedAt === 0) { $this->startedAt = time(); } } public function addStage(PipelineStage $stage): void { $this->stages[$stage->name] = $stage; } public function toArray(): array { $stagesArray = []; foreach ($this->stages as $name => $stage) { $stagesArray[$name] = $stage instanceof PipelineStage ? $stage->toArray() : $stage; } return [ 'id' => $this->id, 'name' => $this->name, 'profile' => $this->profile, 'status' => $this->status, 'branch' => $this->branch, 'commit' => $this->commit, 'stages' => $stagesArray, 'artifacts' => $this->artifacts, 'reports' => $this->reports, 'started_at' => date('Y-m-d H:i:s', $this->startedAt), 'finished_at' => $this->finishedAt ? date('Y-m-d H:i:s', $this->finishedAt) : null, 'duration_seconds' => $this->finishedAt ? ($this->finishedAt - $this->startedAt) : 0 ]; } } 